VAR
    prevMode: BOOL;
    prevSensorA: BOOL;
    prevSensorB: BOOL;
    prevSensorC: BOOL;
    prevButtonA: BOOL;
    prevButtonB: BOOL;
    prevButtonC: BOOL;
    state: INT; // 0=Idle, 1=AtA, 2=MovingAB, 3=AtB, 4=MovingBC, 5=AtC
END_VAR

